.hero-carousel { background: var(--clr-white); padding: 33px 112px 0 104px; }
.hero-carousel__inner { display: flex; flex-direction: column; }
.hero-carousel__heading { font-family: 'Freeman', sans-serif; font-weight: 400; font-size: 4.375rem; line-height: 1; text-transform: uppercase; color: var(--clr-primary); max-width: 1247px; margin: 0 0 38px -8px; }
.hero-carousel__heading-accent { color: var(--clr-sky); }
.hero-carousel__swiper { overflow: hidden; width: 100%; }
.hero-carousel__swiper .swiper-wrapper { display: flex; }
.hero-carousel__slide { width: 572px; }
.hero-carousel__card { position: relative; display: block; width: 572px; height: 592px; border-radius: 51px; overflow: hidden; }
.hero-carousel__card-image { width: 100%; height: 100%; object-fit: cover; }
.hero-carousel__swiper .swiper-slide:nth-child(2) .hero-carousel__card { border-radius: 50px; border: 3px solid var(--clr-sky); box-sizing: border-box; }
.hero-carousel__label { position: absolute; top: 31px; left: 50%; transform: translateX(-50%); min-width: 308px; height: 45px; background: var(--clr-primary); color: var(--clr-white); font-family: 'Freeman', sans-serif; font-size: 1.1875rem; line-height: 40px; text-align: center; white-space: nowrap; border-radius: 13px; padding: 0 16px; }
.hero-carousel__swiper .swiper-slide:nth-child(2) .hero-carousel__label { top: 28px; min-width: 372px; line-height: 45px; }
.hero-carousel__arrow { position: absolute; right: 36px; bottom: 39px; width: 55px; height: 55px; }
.hero-carousel__swiper .swiper-slide:nth-child(2) .hero-carousel__arrow { right: 34px; }
.hero-carousel__meta-row { display: flex; align-items: center; justify-content: space-between; margin-top: 43px; order: 2; }
.hero-carousel__browse-link { display: flex; align-items: center; gap: 32px; margin-left: 46px; font-family: 'Freeman', sans-serif; font-size: 1.125rem; color: var(--clr-primary); text-decoration: none; }
.hero-carousel__pagination.swiper-pagination { position: static !important; width: auto !important; display: flex; gap: 8px; }
.hero-carousel__pagination .swiper-pagination-bullet { width: 24px; height: 24px; border-radius: 50%; background: var(--clr-dot); opacity: 1; }
.hero-carousel__pagination .swiper-pagination-bullet-active { background: var(--clr-primary); }
.hero-carousel__cta-row { display: flex; gap: 34px; order: 1; }
.hero-carousel__cta { display: inline-flex; align-items: center; justify-content: center; height: 50px; border-radius: 5px; font-family: 'Freeman', sans-serif; font-size: 1.125rem; text-decoration: none; }
.hero-carousel__cta--primary { background: var(--clr-primary); color: var(--clr-white); width: 216px; padding: 0 35px; }
.hero-carousel__cta--secondary { background: transparent; color: var(--clr-sky); border: 2px solid var(--clr-sky); width: 288px; padding: 0 88px 0 84px; }
@media (max-width: 1024px) { .hero-carousel { padding: 40px 40px 0; } .hero-carousel__heading { font-size: 3.5rem; } .hero-carousel__slide, .hero-carousel__card { width: 460px; height: 475px; } }
@media (max-width: 768px) { .hero-carousel__swiper .swiper-wrapper { flex-direction: column; } .hero-carousel__slide, .hero-carousel__card { width: 100%; height: auto; aspect-ratio: 572/592; } }
@media (max-width: 430px) { .hero-carousel { background: #FCFEFF; padding: 44px 20px; } .hero-carousel__heading { font-size: 3rem; line-height: 1.15; } .hero-carousel__swiper .swiper-wrapper { flex-direction: column; gap: 18px; } .hero-carousel__slide, .hero-carousel__card { width: 100%; height: auto; aspect-ratio: 390/403.6; border-radius: 34.77px; } .hero-carousel__swiper .swiper-slide:nth-child(2) .hero-carousel__card { border: none; } .hero-carousel__label { font-size: 0.75rem; line-height: 27.27px; height: 30.7px; border-radius: 8.86px; } .hero-carousel__arrow { width: 38px; height: 38px; right: 22px; bottom: 19.6px; } .hero-carousel__meta-row { order: 1; margin-top: 36px; } .hero-carousel__cta-row { order: 2; flex-direction: column; gap: 18px; margin-top: 18px; } .hero-carousel__cta--primary, .hero-carousel__cta--secondary { width: 100%; } }

.procedure-band { background: var(--clr-primary); padding: 51px 62px 58px 76px; }
.procedure-band__heading { font-family: 'Mukta', sans-serif; font-weight: 700; font-size: 2.125rem; line-height: 3.125rem; color: var(--clr-white); max-width: 1137px; margin: 0 0 58px; }
.procedure-band__grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 97px; }
.procedure-band__item { display: flex; flex-direction: column; align-items: flex-start; }
.procedure-band__icon { width: 146px; height: 146px; object-fit: contain; margin-bottom: 10px; }
.procedure-band__title { font-family: 'Montserrat', sans-serif; font-weight: 700; font-size: 1.25rem; line-height: 2.5rem; color: var(--clr-white); margin: 0; }
.procedure-band__link { display: block; font-family: 'Montserrat', sans-serif; font-weight: 700; font-size: 1rem; line-height: 2.5rem; text-decoration: none; }
.procedure-band__link--primary { color: var(--clr-white); }
.procedure-band__link--secondary { color: var(--clr-light-sky); margin-top: 26px; line-height: 1.625rem; }
.procedure-band__closing { display: flex; align-items: center; justify-content: space-between; margin-top: 56px; }
.procedure-band__closing-text { font-family: 'Mukta', sans-serif; font-weight: 700; font-size: 2rem; line-height: 3.125rem; color: var(--clr-white); margin: 0; }
.procedure-band__button { display: flex; align-items: center; justify-content: space-between; gap: 24px; width: 391px; height: 50px; padding: 0 24px 0 19px; background: var(--clr-white); color: var(--clr-primary); border: 2px solid var(--clr-sky); border-radius: 5px; font-family: 'Freeman', sans-serif; font-size: 1.125rem; text-decoration: none; }
@media (max-width: 1024px) { .procedure-band__grid { gap: 48px; } .procedure-band__closing { flex-direction: column; align-items: flex-start; gap: 24px; } }
@media (max-width: 768px) { .procedure-band__grid { grid-template-columns: 1fr; gap: 36px; } .procedure-band__item { flex-direction: row; align-items: flex-start; gap: 24px; } }
@media (max-width: 430px) { .procedure-band { padding: 44px 20px; } .procedure-band__heading { font-size: 1.75rem; line-height: 2.909rem; margin-bottom: 36px; } .procedure-band__item { gap: 0; } .procedure-band__icon { width: 119px; height: 119px; margin-right: 20px; } .procedure-band__text { padding-left: 0; } .procedure-band__title { font-size: 1.125rem; line-height: 1.5rem; } .procedure-band__link--primary { font-size: 0.875rem; } .procedure-band__link--secondary { font-size: 0.875rem; line-height: 1.375rem; margin-top: 22px; } .procedure-band__closing-text { font-size: 1.75rem; line-height: 2.909rem; } .procedure-band__button { width: 100%; border: none; font-size: 1rem; } }

.about-stats { background: var(--clr-white); padding: 95px 76px 99px; text-align: center; }
.about-stats__heading { font-family: 'Freeman', sans-serif; font-weight: 400; font-size: 2.125rem; line-height: 3.125rem; color: var(--clr-primary); text-transform: uppercase; margin: 0 0 21px; }
.about-stats__body { font-family: 'Open Sans', sans-serif; font-size: 1rem; line-height: 2.25rem; color: var(--clr-text); max-width: 1090px; margin: 0 auto 26px; }
.about-stats__row { display: flex; justify-content: center; gap: 79px; margin-top: 44px; }
.about-stats__stat { position: relative; width: 421px; height: 250px; }
.about-stats__panel { position: absolute; left: 0; top: 0; width: 146px; height: 250px; background: var(--clr-white); border-radius: 10px; box-shadow: 21px 0 21px -23px #000000; }
.about-stats__card { position: absolute; left: 131px; top: 44px; width: 290px; height: 162px; border-radius: 20px; background: var(--clr-primary); padding-left: 50px; padding-top: 37px; box-sizing: border-box; display: flex; flex-direction: column; align-items: flex-start; }
.about-stats__stat--sky .about-stats__card { background: var(--clr-sky); }
.about-stats__number { font-family: 'Open Sans', sans-serif; font-weight: 700; font-size: 4rem; line-height: 1.1; color: var(--clr-white); }
.about-stats__label { font-family: 'Open Sans', sans-serif; font-weight: 700; font-size: 1rem; line-height: 1.125rem; color: var(--clr-white); margin-top: 21px; }
.about-stats__button { display: inline-block; margin-top: 20px; background: var(--clr-primary); color: var(--clr-white); font-family: 'Freeman', sans-serif; width: 150px; height: 50px; line-height: 50px; border-radius: 5px; text-decoration: none; }
@media (max-width: 1024px) { .about-stats__row { gap: 32px; } .about-stats__stat { width: 340px; } }
@media (max-width: 768px) { .about-stats__row { flex-direction: column; align-items: center; gap: 32px; } }
@media (max-width: 430px) { .about-stats { padding: 44px 20px; background: #FCFEFF; } .about-stats__heading { font-size: 1.5rem; line-height: 1.995rem; text-transform: uppercase; margin-bottom: 22px; } .about-stats__body { font-size: 0.875rem; line-height: 1.75rem; } .about-stats__row { margin-top: 36px; } .about-stats__stat { width: 350px; height: 250px; } .about-stats__panel { width: 75px; } .about-stats__card { left: 60px; top: 43.2px; } .about-stats__button { width: 100%; } }
